sql.if:
AND EXISTS (SELECT 1 FROM public."JPN_単語収録情報" cr
             WHERE cr."単語ID" = w."単語ID"

               AND cr."分類" >= #{categoryFrom}


               AND cr."分類" <= #{categoryTo}

           )

mapper.select:
SELECT w."単語ID"
AND () IS DISTINCT FROM 'SUCCEEDED' AND () IS DISTINCT FROM 'RUNNING' AND () IS DISTINCT FROM 'QUEUED'
ORDER BY col."書籍" ASC NULLS LAST, col."分類" ASC NULLS LAST, COALESCE(col."単語SEQ", 0) ASC, w."単語ID" ASC LIMIT #{limit}

SELECT "単語ID" AS "wordId", "見出し語" AS "word", "読み" AS "reading"
  FROM public."JPN_単語情報"
 WHERE "見出し語" = #{word}
   AND "読み" IS NOT DISTINCT FROM #{reading}
 LIMIT 1

SELECT count(*)
  FROM public."JPN_単語収録情報"
 WHERE "単語ID" = #{wordId} AND "書籍" = #{book} AND "分類" = #{category}

SELECT MAX("単語SEQ")
  FROM public."JPN_単語収録情報"
 WHERE "書籍" = #{book} AND "分類" = #{category}

SELECT count(*)
  FROM public."JPN_単語収録情報"
 WHERE "書籍" = #{book} AND "分類" = #{category} AND "単語SEQ" = #{wordSeq}

mapper.insert:
INSERT INTO public."JPN_書籍情報" (
    "書籍コード", "書籍名", "分類数", "収録語数", "状態コード",
    "登録者アカウントID", "登録元コード"
) VALUES (
    #{bookCode}, #{bookName}, 0, 0, 'ACTIVE', #{accountId}, 'APP'
)
